            VALUES (?,?,?,?,?,?,?,?)
            """,
            (
                action,
                actor_user_id,
                organization_id,
                target_user_id,
                json.dumps(redact_sensitive(metadata or {})),
                json.dumps(redact_sensitive(before_data or {})),
                json.dumps(redact_sensitive(after_data or {})),
                to_iso(utc_now()),
            ),
        )

    def valid_role(role):
        return role in {"employee", "supervisor", "hr", "admin"}

