                return redirect(url_for("login"))
            return fn(*args, **kwargs)

        return wrapper

    def require_permission(permission):
        def decorator(fn):
            @wraps(fn)
            def wrapper(*args, **kwargs):
                user = current_user()
                if not user:
                    abort(401)
                perms = user_permissions(user["role"])
                if permission not in perms and "admin:all" not in perms:
