        ).fetchone()[0]
        booked = db.execute(
            "SELECT COALESCE(SUM(seats),0) FROM bookings WHERE departure_id=? AND status='confirmed'",
            (departure_id,),
        ).fetchone()[0]
        return max(0, departure["total_seats"] - held - booked)

